/* ═══════════════════════════════════════════════════════════════
   LA ESPADA CELESTIAL — dirección artística
   Paleta: noche profunda, oro viejo, piedra lunar, brasa.
   ═══════════════════════════════════════════════════════════════ */
:root {
  --ink: #070a12;
  --ink-2: #0c1220;
  --panel: rgba(11, 16, 30, .88);
  --panel-2: rgba(17, 24, 42, .92);
  --gold: #e8c37a;
  --gold-2: #b9924d;
  --gold-3: #f7e3ac;
  --parchment: #f2e6cd;
  --muted: #a9a58f;
  --muted-2: #6f756f;
  --line: rgba(232, 195, 122, .22);
  --line-2: rgba(232, 195, 122, .5);
  --hp: #c8454d;
  --hp-2: #7d2029;
  --mp: #4d84c8;
  --st: #d9b855;
  --crit: #ffcf70;
  --display: "Palatino Linotype", "Book Antiqua", Palatino, "Times New Roman", Georgia, serif;
  --body: "Avenir Next", "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
html, body { width: 100%; height: 100%; overflow: hidden; background: #05070d; }
body {
  font-family: var(--body);
  color: var(--parchment);
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}
button, input, select { font-family: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
.hidden { display: none !important; }
.screen { position: fixed; inset: 0; z-index: 40; }

#game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; background: #0b101b; }

#grain {
  position: fixed; inset: 0; z-index: 80; pointer-events: none; opacity: .055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
#letterbox span { display: none; }

/* ───────────── Tipografía base ───────────── */
.eyebrow { font-size: 11px; letter-spacing: .36em; color: var(--gold); text-transform: uppercase; }
h1, h2, h3 { font-family: var(--display); font-weight: 400; letter-spacing: .04em; }

/* ───────────── Botones ───────────── */
.btn {
  position: relative; padding: 13px 30px; min-width: 190px;
  border: 1px solid rgba(232,195,122,.38);
  background: linear-gradient(180deg, rgba(34,42,64,.75), rgba(12,17,30,.85));
  color: var(--parchment); font-size: 12px; letter-spacing: .24em; text-transform: uppercase;
  transition: .25s ease; overflow: hidden;
}
.btn::after {
  content: ""; position: absolute; inset: 3px; border: 1px solid rgba(255,255,255,.05); pointer-events: none;
}
.btn:hover, .btn:focus-visible { border-color: var(--gold); color: #fff5db; box-shadow: 0 0 26px rgba(232,195,122,.18) inset, 0 0 18px rgba(232,195,122,.12); transform: translateY(-1px); }
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: linear-gradient(180deg, #e3bd73, #b3873f 55%, #8f652d);
  color: #1a1207; border-color: #f4deaa; font-weight: 700; text-shadow: 0 1px 0 rgba(255,255,255,.25);
}
.btn-primary:hover { color: #0e0903; box-shadow: 0 0 34px rgba(232,195,122,.45); }
.btn-ghost { background: rgba(8,12,22,.4); border-color: rgba(232,195,122,.18); }
.btn-small { padding: 9px 16px; min-width: 0; font-size: 10px; letter-spacing: .16em; }
.btn-wide { width: 100%; }
.btn:disabled { opacity: .35; pointer-events: none; }

/* ═════════════════ TÍTULO ═════════════════ */
#title-screen {
  display: flex; flex-direction: column; align-items: center; justify-content: space-between;
  padding: clamp(22px, 4vh, 52px) clamp(20px, 5vw, 80px);
  background:
    radial-gradient(ellipse 60% 50% at 50% 62%, rgba(30,40,66,.35), transparent 70%),
    linear-gradient(180deg, rgba(4,7,14,.18) 0%, rgba(4,7,14,.05) 30%, rgba(4,7,14,.55) 78%, rgba(4,7,14,.94) 100%);
  text-align: center;
}
#title-screen::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,.65) 100%);
}
.title-top { position: relative; display: flex; gap: 18px; align-items: center; font-size: 10px; letter-spacing: .52em; color: rgba(242,230,205,.55); }
.sigil { color: var(--gold); opacity: .8; font-size: 12px; }
.title-main { position: relative; display: flex; flex-direction: column; align-items: center; margin-top: auto; padding-bottom: 2vh; }
.title-kicker {
  font-family: var(--display); font-size: clamp(11px, 1.3vw, 16px); font-style: italic;
  color: rgba(242,230,205,.7); letter-spacing: .16em; margin-bottom: 12px;
  animation: fadeUp 1.4s .2s both;
}
.title-main h1 { display: flex; flex-direction: column; line-height: .82; animation: fadeUp 1.8s .1s both; }
.title-main h1 span {
  font-size: clamp(40px, 9.5vw, 138px); letter-spacing: .12em; color: #f5ecd8;
  background: linear-gradient(180deg, #fff8e7 0%, #ecd8a8 38%, #b99555 72%, #7b5c2a 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 26px rgba(232,195,122,.22));
  text-shadow: 0 1px 0 rgba(255,255,255,.12);
}
.title-main h1 em {
  font-style: normal; font-size: clamp(50px, 12vw, 176px); letter-spacing: .2em; padding-left: .2em;
  color: #e8c37a; background: linear-gradient(180deg, #f8e6b7, #e2b968 50%, #92672e);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 36px rgba(232,195,122,.25));
}
.title-sub {
  margin-top: 16px; font-family: var(--display); font-style: italic; font-size: clamp(13px, 1.4vw, 19px);
  color: rgba(242,230,205,.72); letter-spacing: .09em; animation: fadeUp 1.6s .5s both;
}
.title-actions { display: flex; gap: 12px; margin-top: clamp(20px, 4vh, 44px); flex-wrap: wrap; justify-content: center; animation: fadeUp 1.6s .75s both; }
.title-actions .btn { min-width: 170px; }
.title-actions .btn-primary { min-width: 220px; }
.title-bottom {
  position: relative; display: flex; justify-content: space-between; width: 100%;
  font-size: 9px; letter-spacing: .22em; color: rgba(242,230,205,.34); text-transform: uppercase;
}
.title-hint { display: flex; align-items: center; gap: 10px; }
.mini-sound { width: 28px; height: 28px; border: 1px solid var(--line); border-radius: 50%; color: var(--gold); font-size: 13px; }
.title-credit { position: absolute; bottom: 9vh; font-size: 8px; letter-spacing: .55em; color: rgba(232,195,122,.35); animation: pulse 4s infinite; }
@keyframes fadeUp { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes pulse { 0%,100% { opacity: .35; } 50% { opacity: .8; } }

/* ═════════════════ CREACIÓN ═════════════════ */
#create-screen {
  background:
    radial-gradient(ellipse 70% 70% at 20% 40%, rgba(32,46,76,.55), transparent 65%),
    linear-gradient(115deg, #070b14 0%, #0b1120 52%, #070a12 100%);
  display: flex; flex-direction: column; padding: clamp(14px, 2.4vh, 30px) clamp(16px, 3vw, 48px);
  overflow: hidden;
}
#create-screen::after {
  content: ""; position: absolute; inset: 12px; border: 1px solid rgba(232,195,122,.12); pointer-events: none;
}
.create-head { display: flex; align-items: center; gap: 28px; padding-bottom: 14px; border-bottom: 1px solid var(--line); position: relative; z-index: 2; }
.create-head h2 { font-size: clamp(24px, 3vw, 38px); color: var(--parchment); margin-top: 2px; }
.create-head p { max-width: 480px; font-family: var(--display); font-style: italic; font-size: 13px; color: var(--muted); line-height: 1.5; }
.create-head .btn { margin-left: auto; flex-shrink: 0; }
.create-body { flex: 1; display: flex; gap: clamp(20px, 3vw, 52px); min-height: 0; padding-top: 16px; position: relative; z-index: 2; }
.create-preview {
  width: min(34vw, 420px); flex-shrink: 0; display: flex; flex-direction: column; align-items: center;
  justify-content: center; position: relative; border-right: 1px solid rgba(232,195,122,.1);
}
#preview-canvas { width: 100%; height: auto; max-height: 58vh; filter: drop-shadow(0 20px 40px rgba(0,0,0,.5)); }
.preview-caption { text-align: center; margin-top: -4px; }
.preview-caption span { display: block; font-family: var(--display); font-size: 26px; color: var(--gold-3); letter-spacing: .08em; }
.preview-caption small { font-size: 9px; letter-spacing: .32em; color: var(--muted); text-transform: uppercase; }
.preview-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px 16px; margin-top: 14px; width: 88%; }
.preview-stats div { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); border-bottom: 1px dotted rgba(255,255,255,.08); padding-bottom: 3px; }
.preview-stats b { color: var(--parchment); font-weight: 500; }
.create-form { flex: 1; overflow-y: auto; padding-right: 10px; padding-bottom: 20px; scrollbar-width: thin; scrollbar-color: var(--gold-2) transparent; }
.create-form::-webkit-scrollbar { width: 5px; }
.create-form::-webkit-scrollbar-thumb { background: var(--gold-2); }
.field-row { display: flex; gap: 14px; }
.field { flex: 1; display: flex; flex-direction: column; gap: 6px; }
.field span { font-size: 9px; letter-spacing: .28em; color: var(--gold); }
.field input, .field select {
  background: rgba(255,255,255,.035); border: 1px solid rgba(232,195,122,.18); padding: 12px 14px;
  font-size: 15px; font-family: var(--display); color: var(--parchment); outline: none; transition: .2s;
}
.field input:focus, .field select:focus { border-color: var(--gold); background: rgba(232,195,122,.06); }
.field select option { background: #111827; }
.section-label { display: flex; align-items: center; gap: 14px; margin: 20px 0 10px; }
.section-label span { font-size: 9px; letter-spacing: .32em; color: var(--gold); }
.section-label i { flex: 1; height: 1px; background: linear-gradient(90deg, var(--line), transparent); }
.section-label small { font-size: 9px; color: var(--muted); letter-spacing: .1em; }
.class-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.class-card {
  position: relative; text-align: left; padding: 12px 13px; min-height: 98px;
  border: 1px solid rgba(232,195,122,.14); background: rgba(255,255,255,.025);
  transition: .22s; color: var(--parchment); overflow: hidden;
}
.class-card:hover { border-color: rgba(232,195,122,.45); background: rgba(232,195,122,.05); }
.class-card.active { border-color: var(--gold); background: linear-gradient(160deg, rgba(232,195,122,.12), rgba(232,195,122,.02)); box-shadow: 0 0 24px rgba(232,195,122,.08) inset; }
.class-card.active::before { content: "✦"; position: absolute; top: 8px; right: 10px; color: var(--gold); font-size: 10px; }
.class-card b { display: block; font-family: var(--display); font-size: 15px; color: var(--gold-3); margin-bottom: 4px; }
.class-card small { display: block; font-size: 9.5px; line-height: 1.45; color: var(--muted); }
.class-card em { display: block; margin-top: 6px; font-size: 8.5px; letter-spacing: .08em; color: var(--gold-2); font-style: normal; }
.appearance-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px 16px; }
.app-row { display: flex; align-items: center; gap: 8px; }
.app-row > span { width: 64px; font-size: 8.5px; letter-spacing: .16em; color: var(--muted); text-transform: uppercase; flex-shrink: 0; }
.swatches { display: flex; gap: 5px; flex-wrap: wrap; }
.swatch { width: 23px; height: 23px; border-radius: 50%; border: 2px solid transparent; outline: 1px solid rgba(255,255,255,.15); transition: .15s; }
.swatch.active { border-color: var(--gold-3); transform: scale(1.1); }
.opt-btn {
  padding: 5px 9px; font-size: 9px; letter-spacing: .06em; border: 1px solid rgba(255,255,255,.1);
  color: var(--muted); transition: .15s; background: rgba(255,255,255,.02);
}
.opt-btn.active { border-color: var(--gold); color: var(--gold-3); background: rgba(232,195,122,.08); }
.stat-alloc { display: grid; grid-template-columns: repeat(2, 1fr); gap: 5px 20px; }
.stat-line { display: flex; align-items: center; gap: 8px; padding: 4px 0; border-bottom: 1px dotted rgba(255,255,255,.06); }
.stat-line .sn { flex: 1; font-size: 10px; color: var(--muted); letter-spacing: .06em; }
.stat-line .sv { width: 24px; text-align: center; font-size: 12px; color: var(--parchment); }
.stat-line button { width: 20px; height: 20px; border: 1px solid rgba(232,195,122,.25); color: var(--gold); font-size: 11px; line-height: 1; }
.stat-line button:disabled { opacity: .2; }
.stat-line .eff { width: 60px; font-size: 8px; color: var(--muted-2); text-align: right; }
.create-footer { display: flex; align-items: center; gap: 20px; margin-top: 18px; }
.create-footer p { flex: 1; font-family: var(--display); font-style: italic; font-size: 11px; color: var(--muted); }
.create-footer .btn { min-width: 200px; flex-shrink: 0; }

/* ═════════════════ HUD ═════════════════ */
#hud { position: fixed; inset: 0; z-index: 20; pointer-events: none; }
.hud-vitals {
  position: absolute; top: calc(14px + env(safe-area-inset-top, 0px)); left: calc(16px + var(--safe-l));
  display: flex; gap: 10px; align-items: flex-start; pointer-events: none;
  filter: drop-shadow(0 3px 8px rgba(0,0,0,.6));
}
.portrait-ring { position: relative; width: 68px; height: 68px; flex-shrink: 0; }
.portrait-ring canvas { width: 100%; height: 100%; border-radius: 50%; background: radial-gradient(circle at 40% 30%, #2a3550, #0a0d16); border: 1px solid rgba(232,195,122,.55); box-shadow: 0 0 0 3px rgba(7,10,18,.7), 0 0 0 4px rgba(232,195,122,.18); }
.portrait-ring .lvl {
  position: absolute; bottom: -3px; right: -3px; width: 22px; height: 22px; border-radius: 50%;
  background: linear-gradient(180deg, #e8c37a, #9c7434); color: #14100a; font-style: normal;
  display: grid; place-items: center; font-size: 10px; font-weight: 800; border: 2px solid #0a0d16;
}
.vital-stack { width: clamp(210px, 23vw, 300px); }
.vital-name { display: flex; align-items: baseline; gap: 8px; margin-bottom: 4px; }
.vital-name span { font-family: var(--display); font-size: 16px; letter-spacing: .06em; color: #f6ecd6; text-shadow: 0 1px 4px #000; }
.vital-name small { font-size: 8px; letter-spacing: .18em; color: var(--gold); text-transform: uppercase; opacity: .85; }
.bar { position: relative; height: 11px; background: rgba(4,7,13,.78); border: 1px solid rgba(255,255,255,.12); margin-bottom: 3px; overflow: hidden; }
.bar-fill { position: absolute; inset: 0; width: 100%; transform-origin: left; transition: width .18s ease; }
.bar.hp .bar-fill { background: linear-gradient(180deg, #e1656b, #a82e3a 60%, #741b26); }
.bar.mp { height: 8px; }
.bar.mp .bar-fill { background: linear-gradient(180deg, #7db5ef, #3e6da8 60%, #244b7c); }
.bar.st { height: 6px; }
.bar.st .bar-fill { background: linear-gradient(180deg, #efd47c, #bf9c3f 60%, #8a6b21); }
.bar span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 7.5px; letter-spacing: .08em; color: rgba(255,255,255,.82); text-shadow: 0 1px 2px #000; }
.xp { height: 2px; background: rgba(255,255,255,.1); margin-top: 3px; }
.xp div { height: 100%; width: 0; background: var(--gold); box-shadow: 0 0 6px var(--gold); transition: width .3s; }
.hud-right {
  position: absolute; top: calc(12px + env(safe-area-inset-top, 0px)); right: calc(16px + var(--safe-r));
  display: flex; flex-direction: column; align-items: flex-end; gap: 6px; width: clamp(180px, 20vw, 250px);
}
.region-chip { text-align: right; }
.region-chip span { display: block; font-family: var(--display); font-size: 15px; letter-spacing: .28em; color: var(--gold-3); text-shadow: 0 2px 8px #000; }
.region-chip small { font-size: 8px; letter-spacing: .24em; color: var(--muted); text-transform: uppercase; }
.minimap-wrap { position: relative; width: clamp(116px, 14vw, 158px); height: clamp(116px, 14vw, 158px); margin-top: 2px; }
#minimap { width: 100%; height: 100%; border-radius: 50%; border: 1px solid rgba(232,195,122,.5); background: #0a0f18; box-shadow: 0 0 0 4px rgba(7,10,18,.55), 0 0 30px rgba(0,0,0,.5); }
.mm-ring { position: absolute; inset: 5px; border-radius: 50%; border: 1px solid rgba(232,195,122,.16); pointer-events: none; }
.mm-n { position: absolute; top: -7px; left: 50%; transform: translateX(-50%); font-size: 7px; color: var(--gold); letter-spacing: .1em; }
.quest-chip { width: 100%; text-align: right; background: linear-gradient(270deg, rgba(7,10,18,.8), transparent); padding: 6px 8px 6px 24px; border-right: 2px solid var(--gold); }
.quest-chip .q-label { display: block; font-size: 7px; letter-spacing: .3em; color: var(--gold-2); }
.quest-chip b { display: block; font-family: var(--display); font-size: 12px; color: #f3e8d0; font-weight: 400; line-height: 1.35; margin: 2px 0; }
.quest-chip small { font-size: 8px; color: var(--muted); letter-spacing: .08em; }
.currency { display: flex; align-items: center; gap: 5px; font-size: 10px; color: var(--parchment); }
.currency b { font-weight: 500; margin-right: 7px; }
.ico-shard, .ico-gold { display: inline-block; width: 9px; height: 9px; transform: rotate(45deg); }
.ico-shard { background: linear-gradient(135deg, #b7e4ff, #4f8fc9); box-shadow: 0 0 6px #6db9ee; }
.ico-gold { background: linear-gradient(135deg, #ffe9a8, #b78a32); border-radius: 50%; box-shadow: 0 0 6px #e8c37a; }
.companion-chip {
  position: absolute; left: calc(20px + var(--safe-l)); bottom: calc(100px + var(--safe-b));
  display: flex; align-items: center; gap: 8px; background: rgba(8,12,22,.7); border: 1px solid rgba(232,195,122,.2);
  padding: 6px 12px 6px 6px; backdrop-filter: blur(6px); border-radius: 30px;
}
.companion-chip canvas { width: 36px; height: 36px; border-radius: 50%; background: #101827; }
.companion-chip small { display: block; font-size: 6.5px; letter-spacing: .22em; color: var(--gold-2); }
.companion-chip b { display: block; font-family: var(--display); font-size: 12px; font-weight: 400; }
.comp-hp { width: 54px; height: 3px; background: rgba(255,255,255,.15); margin-top: 3px; }
.comp-hp i { display: block; height: 100%; width: 100%; background: #65c9a2; transition: width .2s; }

.boss-wrap {
  position: absolute; top: calc(12px + env(safe-area-inset-top, 0px)); left: 50%; transform: translateX(-50%);
  width: min(620px, 56vw); text-align: center;
}
.boss-head span { display: block; font-size: 8px; letter-spacing: .42em; color: #d58d7a; text-transform: uppercase; }
.boss-head b { display: block; font-family: var(--display); font-size: clamp(16px, 2vw, 24px); font-weight: 400; letter-spacing: .1em; color: #f7e8d6; text-shadow: 0 2px 14px #000; margin-bottom: 5px; }
.boss-bar { position: relative; height: 9px; background: rgba(5,7,12,.8); border: 1px solid rgba(232,195,122,.3); overflow: hidden; }
.boss-bar i { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; background: linear-gradient(180deg, #b8463f, #701c25); transition: width .2s; }
.boss-bar em { position: absolute; left: 0; top: 0; bottom: 0; width: 100%; background: #e9c47c; opacity: .5; transition: width .7s .25s; }
.boss-phase { font-size: 8px; letter-spacing: .3em; color: #c9a56a; margin-top: 3px; text-transform: uppercase; }

.combo-indicator {
  position: absolute; right: calc(34px + var(--safe-r)); top: 38%; text-align: right; opacity: 0; transition: opacity .3s; transform-origin: right;
}
.combo-indicator.show { opacity: 1; }
.combo-indicator b { font-family: var(--display); font-size: 40px; color: var(--gold-3); text-shadow: 0 0 20px rgba(232,195,122,.5), 0 2px 6px #000; }
.combo-indicator span { font-size: 7px; letter-spacing: .35em; color: var(--gold); display: block; margin-top: -6px; }
.interact-prompt {
  position: absolute; left: 50%; bottom: 21%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px; padding: 8px 18px;
  background: rgba(7,10,18,.82); border: 1px solid var(--line-2); font-size: 11px; letter-spacing: .14em;
  animation: promptIn .25s ease; backdrop-filter: blur(4px);
}
.interact-prompt kbd { display: grid; place-items: center; width: 24px; height: 24px; border: 1px solid var(--gold); color: var(--gold); font-family: var(--body); font-size: 11px; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 8px); } }

.skill-cooldowns { position: absolute; right: calc(26px + var(--safe-r)); bottom: calc(188px + var(--safe-b)); display: flex; gap: 6px; }
.skill-slot {
  width: 40px; height: 40px; border: 1px solid rgba(232,195,122,.25); background: rgba(7,10,18,.7);
  position: relative; display: grid; place-items: center; color: var(--gold-3); font-size: 14px;
}
.skill-slot small { position: absolute; bottom: 1px; right: 3px; font-size: 6px; color: var(--muted); }
.skill-slot .cd { position: absolute; inset: 0; background: rgba(4,6,10,.75); display: grid; place-items: center; font-size: 12px; color: #fff; }
.skill-slot.locked { opacity: .3; }

.toast-layer { position: absolute; top: 26%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; width: 80%; }
.toast {
  padding: 7px 20px; background: rgba(7,10,18,.8); border: 1px solid rgba(232,195,122,.25);
  font-family: var(--display); font-size: 13px; color: var(--parchment); letter-spacing: .06em;
  animation: toastIn .35s ease, toastOut .5s 2.5s both; backdrop-filter: blur(6px);
}
.toast.gold { border-color: var(--gold); color: var(--gold-3); box-shadow: 0 0 30px rgba(232,195,122,.15); }
.toast.danger { border-color: #b8463f; color: #ffd5cf; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px) scale(.97); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }
.subtitle { position: absolute; bottom: 12%; left: 50%; transform: translateX(-50%); width: min(720px, 80%); text-align: center; font-family: var(--display); font-size: 15px; color: #f3ead7; text-shadow: 0 2px 8px #000; line-height: 1.4; opacity: 0; transition: opacity .3s; }
.subtitle.show { opacity: 1; }
.danger-vignette { position: absolute; inset: 0; box-shadow: inset 0 0 140px rgba(160,20,30,.55); opacity: 0; transition: opacity .4s; }
.danger-vignette.show { opacity: 1; }

/* táctil */
#touch-ui { position: absolute; inset: 0; pointer-events: none; }
.joystick {
  position: absolute; left: calc(30px + var(--safe-l)); bottom: calc(26px + var(--safe-b));
  width: 140px; height: 140px; border-radius: 50%; pointer-events: auto;
  background: radial-gradient(circle, rgba(232,195,122,.06), rgba(7,10,18,.18) 60%, transparent 70%);
  touch-action: none;
}
.js-ring { position: absolute; inset: 8px; border-radius: 50%; border: 1px solid rgba(232,195,122,.22); }
.js-knob {
  position: absolute; left: 50%; top: 50%; width: 54px; height: 54px; border-radius: 50%;
  transform: translate(-50%, -50%); background: radial-gradient(circle at 40% 32%, rgba(247,227,172,.28), rgba(20,28,46,.75));
  border: 1px solid rgba(232,195,122,.55); box-shadow: 0 4px 16px rgba(0,0,0,.5);
}
.action-cluster { position: absolute; right: calc(24px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); width: 190px; height: 168px; pointer-events: none; }
.act {
  position: absolute; pointer-events: auto; display: grid; place-items: center;
  background: radial-gradient(circle at 38% 30%, rgba(49,62,92,.85), rgba(8,12,22,.9));
  border: 1px solid rgba(232,195,122,.38); color: #f0e3c8; border-radius: 50%;
  box-shadow: 0 6px 20px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.15);
  transition: transform .08s, background .15s; touch-action: none;
}
.act:active { transform: scale(.92); background: radial-gradient(circle, rgba(232,195,122,.35), rgba(20,28,46,.95)); }
.act svg { width: 26px; height: 26px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 1px 2px #000); }
.act span { position: absolute; bottom: -13px; font-size: 7px; letter-spacing: .14em; color: rgba(232,195,122,.65); }
.act-attack { width: 86px; height: 86px; right: 8px; bottom: 6px; border-color: rgba(232,195,122,.65); background: radial-gradient(circle at 36% 30%, rgba(94,78,48,.9), rgba(14,17,27,.94)); }
.act-attack svg { width: 38px; height: 38px; }
.act-dodge { width: 54px; height: 54px; right: 100px; bottom: 14px; }
.act-block { width: 50px; height: 50px; right: 24px; bottom: 96px; }
.act-block svg { width: 22px; }
.act-summon { width: 44px; height: 44px; right: 82px; bottom: 84px; }
.act-summon svg { width: 20px; }
.act-interact { width: 58px; height: 58px; right: 84px; bottom: 142px; border-color: var(--gold); color: var(--gold-3); animation: promptPulse 1.4s infinite; }
.act-interact svg { width: 24px; }
@keyframes promptPulse { 0%,100% { box-shadow: 0 0 0 0 rgba(232,195,122,.25), 0 6px 20px rgba(0,0,0,.45); } 50% { box-shadow: 0 0 0 8px rgba(232,195,122,0), 0 6px 20px rgba(0,0,0,.45); } }
.skill-wheel { position: absolute; right: calc(232px + var(--safe-r)); bottom: calc(26px + var(--safe-b)); display: flex; gap: 7px; pointer-events: none; }
.skill-wheel .skill-slot { pointer-events: auto; width: 44px; height: 44px; border-radius: 50%; }
.hud-icon-btn {
  position: absolute; width: 38px; height: 38px; border: 1px solid rgba(232,195,122,.28); border-radius: 50%;
  background: rgba(7,10,18,.65); color: var(--gold); display: grid; place-items: center; pointer-events: auto;
}
.hud-icon-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.5; }
#btn-menu { right: calc(18px + var(--safe-r)); top: calc(14px + env(safe-area-inset-top, 0px)); }
.map-btn { right: calc(64px + var(--safe-r)); top: calc(14px + env(safe-area-inset-top, 0px)); }

/* ═════════════════ DIÁLOGO ═════════════════ */
#dialog { position: fixed; inset: 0; z-index: 30; display: flex; align-items: flex-end; justify-content: center; padding: 0 4vw calc(4vh + var(--safe-b)); pointer-events: none; background: linear-gradient(0deg, rgba(3,5,10,.65), transparent 45%); }
.dialog-box {
  width: min(1080px, 92vw); display: flex; pointer-events: auto;
  background: linear-gradient(105deg, rgba(12,17,30,.96), rgba(9,13,24,.92));
  border: 1px solid rgba(232,195,122,.35); box-shadow: 0 24px 80px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.06);
  position: relative; animation: dialogIn .28s ease;
}
.dialog-box::before { content: ""; position: absolute; inset: 5px; border: 1px solid rgba(232,195,122,.1); pointer-events: none; }
@keyframes dialogIn { from { opacity: 0; transform: translateY(16px); } }
.dialog-portrait { width: 190px; flex-shrink: 0; position: relative; overflow: hidden; background: radial-gradient(ellipse at 50% 35%, #273451, #0a0e18); border-right: 1px solid rgba(232,195,122,.18); }
.dialog-portrait canvas { width: 100%; height: 100%; object-fit: cover; display: block; }
.dialog-body { flex: 1; padding: 18px 26px 16px; min-height: 176px; display: flex; flex-direction: column; }
.dialog-head { display: flex; align-items: baseline; gap: 12px; border-bottom: 1px solid rgba(232,195,122,.15); padding-bottom: 7px; margin-bottom: 9px; }
.dialog-head span { font-family: var(--display); font-size: 20px; color: var(--gold-3); letter-spacing: .05em; }
.dialog-head small { font-size: 8px; letter-spacing: .2em; color: var(--muted); text-transform: uppercase; }
#dialog-text { font-family: var(--display); font-size: clamp(14px, 1.5vw, 18px); line-height: 1.55; color: #efe6d4; min-height: 56px; flex: 1; }
#dialog-text .accent { color: var(--gold); }
.dialog-next { align-self: flex-end; font-size: 9px; letter-spacing: .24em; color: var(--gold); margin-top: 6px; padding: 4px; }
.dialog-next span { display: inline-block; animation: nudge 1.2s infinite; }
@keyframes nudge { 50% { transform: translateX(4px); } }
.dialog-choices { display: flex; flex-direction: column; gap: 6px; margin: 8px 0 4px; }
.dialog-choices button {
  text-align: left; padding: 9px 14px; border: 1px solid rgba(232,195,122,.2);
  background: rgba(255,255,255,.025); font-family: var(--display); font-size: 13px; color: #e8ddc8; transition: .15s;
}
.dialog-choices button:hover { border-color: var(--gold); background: rgba(232,195,122,.08); color: #fff; padding-left: 20px; }
.dialog-choices button::before { content: "◇ "; color: var(--gold-2); }

/* ═════════════════ CINEMÁTICA ═════════════════ */
#cinematic { position: fixed; inset: 0; z-index: 60; background: #04060b; }
.cine-backdrop { position: absolute; inset: 0; }
.cine-backdrop canvas { width: 100%; height: 100%; }
.cine-bars i { position: absolute; left: 0; right: 0; height: 9vh; background: #000; z-index: 2; }
.cine-bars i:first-child { top: 0; }
.cine-bars i:last-child { bottom: 0; }
.cine-content {
  position: absolute; left: 50%; bottom: 15vh; transform: translateX(-50%); width: min(760px, 84vw); z-index: 3;
  text-align: center; padding: 30px 20px;
}
.cine-chapter { display: block; font-size: 9px; letter-spacing: .5em; color: var(--gold-2); margin-bottom: 14px; text-transform: uppercase; }
.cine-text { font-family: var(--display); font-size: clamp(17px, 2vw, 25px); line-height: 1.7; color: #f2e8d4; text-shadow: 0 3px 18px #000; min-height: 90px; }
.cine-text em { color: var(--gold-3); font-style: italic; }
.cine-continue { display: block; margin-top: 26px; font-size: 8px; letter-spacing: .32em; color: rgba(242,232,212,.45); animation: pulse 2.2s infinite; }
.skip-btn { position: absolute; top: calc(11vh + 12px); right: 5vw; z-index: 5; font-size: 9px; letter-spacing: .22em; color: rgba(242,232,212,.55); padding: 8px 14px; border: 1px solid rgba(255,255,255,.12); }
.skip-btn:hover { color: var(--gold); border-color: var(--gold-2); }

/* ═════════════════ MENÚ ═════════════════ */
#menu { background: rgba(4,7,13,.82); backdrop-filter: blur(10px); z-index: 50; padding: clamp(10px, 2.4vh, 26px); }
.menu-shell { width: 100%; height: 100%; display: flex; border: 1px solid rgba(232,195,122,.18); background: linear-gradient(110deg, rgba(9,13,24,.96), rgba(13,19,34,.94)); position: relative; overflow: hidden; }
.menu-shell::before { content: ""; position: absolute; inset: 0; background: radial-gradient(ellipse at 0% 100%, rgba(55,72,110,.22), transparent 55%); pointer-events: none; }
.menu-side { width: clamp(180px, 18vw, 240px); flex-shrink: 0; border-right: 1px solid rgba(232,195,122,.14); padding: 26px 18px; display: flex; flex-direction: column; position: relative; z-index: 1; }
.menu-brand { display: flex; gap: 10px; align-items: flex-start; margin-bottom: 30px; }
.menu-brand span { color: var(--gold); font-size: 18px; }
.menu-brand b { font-family: var(--display); font-size: 13px; letter-spacing: .18em; font-weight: 400; color: var(--gold-3); line-height: 1.4; }
#menu-tabs { display: flex; flex-direction: column; gap: 2px; }
#menu-tabs button {
  text-align: left; padding: 11px 12px; font-size: 10px; letter-spacing: .2em; color: var(--muted);
  border-left: 2px solid transparent; transition: .2s;
}
#menu-tabs button:hover { color: var(--parchment); background: rgba(255,255,255,.03); }
#menu-tabs button.active { color: var(--gold-3); border-left-color: var(--gold); background: linear-gradient(90deg, rgba(232,195,122,.1), transparent); }
.menu-side-foot { margin-top: auto; display: flex; flex-direction: column; gap: 10px; align-items: flex-start; }
.menu-side-foot span { font-size: 9px; letter-spacing: .2em; color: var(--muted-2); }
.menu-content { flex: 1; overflow-y: auto; padding: clamp(20px, 3vw, 40px) clamp(22px, 3.4vw, 52px); position: relative; z-index: 1; scrollbar-width: thin; scrollbar-color: var(--gold-2) transparent; }
.menu-content::-webkit-scrollbar { width: 5px; }
.menu-content::-webkit-scrollbar-thumb { background: var(--gold-2); }
.menu-close { position: absolute; right: 18px; top: 16px; width: 34px; height: 34px; border: 1px solid rgba(232,195,122,.25); color: var(--gold); z-index: 3; font-size: 14px; }
.menu-close:hover { border-color: var(--gold); background: rgba(232,195,122,.1); }
.menu-title { display: flex; align-items: flex-end; gap: 16px; margin-bottom: 18px; }
.menu-title h2 { font-size: clamp(24px, 3vw, 38px); color: var(--gold-3); }
.menu-title p { font-family: var(--display); font-size: 12px; font-style: italic; color: var(--muted); margin-bottom: 5px; }
.menu-title .right { margin-left: auto; }

.char-grid { display: grid; grid-template-columns: minmax(240px, 340px) 1fr; gap: 24px; align-items: start; }
.char-card { border: 1px solid rgba(232,195,122,.16); background: rgba(255,255,255,.02); padding: 18px; }
.char-hero { display: flex; align-items: center; gap: 14px; margin-bottom: 14px; }
.char-hero canvas { width: 76px; height: 76px; border-radius: 50%; border: 1px solid var(--gold-2); background: #0d1422; }
.char-hero b { display: block; font-family: var(--display); font-size: 20px; font-weight: 400; color: var(--gold-3); }
.char-hero small { display: block; font-size: 8px; letter-spacing: .2em; color: var(--muted); text-transform: uppercase; margin-top: 3px; }
.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 18px; }
.stat-grid div { display: flex; justify-content: space-between; padding: 4px 0; border-bottom: 1px dotted rgba(255,255,255,.07); font-size: 10px; color: var(--muted); }
.stat-grid b { color: var(--parchment); font-weight: 500; }
.derived { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 14px; }
.derived div { text-align: center; padding: 8px 4px; background: rgba(255,255,255,.025); border: 1px solid rgba(255,255,255,.05); }
.derived span { display: block; font-size: 7px; letter-spacing: .14em; color: var(--muted-2); text-transform: uppercase; }
.derived b { font-family: var(--display); font-size: 16px; color: var(--gold-3); font-weight: 400; }
.equip-panel { display: flex; flex-direction: column; gap: 6px; }
.equip-row { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.02); font-size: 10px; }
.equip-row .slot { width: 58px; font-size: 7.5px; letter-spacing: .14em; color: var(--muted-2); text-transform: uppercase; flex-shrink: 0; }
.equip-row .item-name { flex: 1; color: var(--parchment); }
.equip-row .item-name small { color: var(--gold-2); margin-left: 6px; font-size: 8px; }
.equip-row .empty { color: var(--muted-2); font-style: italic; }
.equip-row button { font-size: 8px; letter-spacing: .1em; color: var(--gold); border: 1px solid rgba(232,195,122,.2); padding: 4px 8px; }
.equip-row button:hover { background: rgba(232,195,122,.1); }
.tabs-mini { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }
.tabs-mini button { padding: 6px 12px; border: 1px solid rgba(255,255,255,.08); font-size: 9px; letter-spacing: .12em; color: var(--muted); }
.tabs-mini button.active { border-color: var(--gold-2); color: var(--gold-3); background: rgba(232,195,122,.07); }

.skills-wrap { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.skill-branch { border: 1px solid rgba(232,195,122,.13); padding: 12px; background: rgba(255,255,255,.015); }
.skill-branch h4 { font-family: var(--display); font-size: 14px; font-weight: 400; color: var(--gold-3); letter-spacing: .06em; margin-bottom: 2px; }
.skill-branch > small { font-size: 7.5px; letter-spacing: .16em; color: var(--muted-2); text-transform: uppercase; }
.skill-node { margin-top: 9px; padding: 7px 8px; border: 1px solid rgba(255,255,255,.07); background: rgba(0,0,0,.18); position: relative; }
.skill-node.unlocked { border-color: rgba(232,195,122,.45); background: rgba(232,195,122,.06); }
.skill-node.available { border-color: rgba(232,195,122,.25); }
.skill-node b { display: flex; justify-content: space-between; font-size: 10px; color: var(--parchment); font-weight: 500; }
.skill-node b i { font-style: normal; font-size: 8px; color: var(--gold); }
.skill-node small { display: block; font-size: 8.5px; color: var(--muted); line-height: 1.4; margin-top: 3px; }
.skill-node button { width: 100%; margin-top: 5px; padding: 3px; font-size: 7.5px; letter-spacing: .14em; border: 1px solid rgba(232,195,122,.25); color: var(--gold); }
.skill-node button:hover { background: rgba(232,195,122,.12); }
.skill-node button:disabled { opacity: .3; }

.inv-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 8px; }
.inv-item { display: flex; gap: 10px; padding: 10px; border: 1px solid rgba(255,255,255,.07); background: rgba(255,255,255,.02); align-items: flex-start; }
.inv-item:hover { border-color: rgba(232,195,122,.3); }
.item-glyph { width: 34px; height: 34px; flex-shrink: 0; display: grid; place-items: center; border: 1px solid rgba(232,195,122,.25); color: var(--gold); background: radial-gradient(circle at 35% 30%, #26314a, #0d1320); font-size: 16px; }
.inv-item .meta { flex: 1; min-width: 0; }
.inv-item b { display: block; font-size: 10.5px; color: var(--parchment); font-weight: 500; }
.inv-item small { display: block; font-size: 8px; color: var(--muted); line-height: 1.4; margin-top: 2px; }
.inv-item .qty { font-family: var(--display); color: var(--gold-3); font-size: 12px; }
