469: export function isBlockedRaw(world, x, y, r, props, solid, W, H) {
470:   if (x < TILE || y < TILE || x > (W - 1) * TILE || y > (H - 1) * TILE) return true;
471:   const tx0 = Math.floor((x - r) / TILE), tx1 = Math.floor((x + r) / TILE);
472:   const ty0 = Math.floor((y - r) / TILE), ty1 = Math.floor((y + r) / TILE);
473:   for (let ty = ty0; ty <= ty1; ty++) {
474:     for (let tx = tx0; tx <= tx1; tx++) {
475:       if (tx < 0 || ty < 0 || tx >= W || ty >= H) return true;
476:       if (solid[ty * W + tx]) {
477:         if (circleRect(x, y, r, tx * TILE, ty * TILE, TILE, TILE)) return true;
478:       }
479:     }
480:   }
481:   for (const p of props) {
482:     if (!p.solid || p.visible === false || p.harvested) continue;
483:     if (Math.abs(p.x - x) > 360 || Math.abs(p.y - y) > 360) continue;
484:     if (p.rect) {
485:       if (circleRect(x, y, r, p.rect.x, p.rect.y, p.rect.w, p.rect.h)) return true;
486:     } else if (p.r) {
487:       if ((p.x - x) ** 2 + (p.y - y) ** 2 < (p.r + r) ** 2) return true;
488:     }
489:   }
490:   return false;
491: }
