493: export function freeSpot(world, cx, cy, radius, rng = Math.random, pad = 20) {
494:   for (let i = 0; i < 80; i++) {
495:     const a = rng() * Math.PI * 2;
496:     const d = Math.sqrt(rng()) * radius;
497:     const x = cx + Math.cos(a) * d, y = cy + Math.sin(a) * d;
498:     if (world.isBlocked(x, y, pad)) continue;
499:     if (world.def.pois.some(p => {
500:       if (!p.safe) return false;
501:       return dist(x, y, p.x * TILE + TILE / 2, p.y * TILE + TILE / 2) < p.safe * TILE * .42;
502:     })) continue;
503:     return { x, y };
504:   }
505:   return null;
506: }
