508: export function markExplored(world, x, y, radius = 6) {
509:   const cx = Math.floor(x / TILE), cy = Math.floor(y / TILE);
510:   for (let ty = cy - radius; ty <= cy + radius; ty++) {
511:     for (let tx = cx - radius; tx <= cx + radius; tx++) {
512:       if (tx < 0 || ty < 0 || tx >= world.W || ty >= world.H) continue;
513:       if ((tx - cx) ** 2 + (ty - cy) ** 2 <= radius * radius) world.explored[ty * world.W + tx] = 1;
514:     }
515:   }
516: }
