518: export function findInteractable(world, x, y, maxDist = 65) {
519:   let best = null, bestD = maxDist;
520:   for (const it of world.interactables) {
521:     if (it.disabled) continue;
522:     if (it.type === 'npc') {
523:       const npc = it.npc;
524:       if (npc.hidden) continue;
525:     }
526:     const d = dist(x, y, it.x, it.y);
527:     if (d < bestD) { best = it; bestD = d; }
528:   }
529:   return best;
530: }
