509: export function specialUpdate(game) {
510:   // Kael espera en el Templo antes del duelo.
511:   if (game.regionId === 'kansordore' && !game.flags.kael_duel_started && !game.flags.kael_resolved) {
512:     const q = game.quests.velo;
513:     if (q && !q.done && q.stage === 3) {
514:       const k = game.world.npcs.find(n => n.id === 'kael_k');
515:       if (k) {
516:         k.hidden = false;
517:         k.marker = true;
518:         const p = game.world.def.pois.find(p => p.id === 'temple');
519:         if (p) {
520:           k.x = p.x * 64 + 32 + 90;
521:           k.y = p.y * 64 + 32 + 30;
522:         }
523:       }
524:     }
525:   }
526:   // Aparición de la Voz al llegar a la Falla.
527:   if (game.regionId === 'kansordore' && game.quests.velo && game.quests.velo.stage === 5 && !game.flags.voz_started) {
528:     const a = game.world.bossArena;
529:     if (a && Math.hypot(game.player.x - a.x, game.player.y - a.y) < a.r * .8) {
530:       game.setFlag('voz_started', true);
531:       game.spawnBoss('boss_voz', a.x, a.y);
532:     }
533:   }
534: }
