    }
    if (p.state === 'attack') {
      const move = p.stateT < p.attackDuration * .55 ? .22 : .05;
      if (this.movement.len > .1) this.tryMove(p, this.movement.x * p.speed * move * dt, this.movement.y * p.speed * move * dt);
