    options.forEach((o, i) => {
      const b = el('button', 'opt-btn' + (active === i ? ' active' : ''), escapeHTML(o));
      b.addEventListener('click', () => { audio.sfx?.('click'); set(i); this.renderCreate(); });
      wrap.appendChild(b);
    });
