import fs from 'fs';
const files = fs.readdirSync('js').filter(f=>f.endsWith('.js'));
const exportsMap = {};
for (const f of files) {
  const s = fs.readFileSync('js/'+f,'utf8');
  const names = new Set();
  for (const m of s.matchAll(/export\s+(?:async\s+)?(?:class|function|const|let|var)\s+([A-Za-z0-9_$]+)/g)) names.add(m[1]);
  for (const m of s.matchAll(/export\s*\{([^}]+)\}/g)) m[1].split(',').forEach(x=>{const p=x.trim().split(/\s+as\s+/); if(p[0]) names.add(p.at(-1));});
  exportsMap[f]=names;
}
let bad=0;
for (const f of files) {
  const s = fs.readFileSync('js/'+f,'utf8');
  for (const m of s.matchAll(/import\s*\{([^}]+)\}\s*from\s*['"]\.\/([^'"]+)['"]/g)) {
    const target=m[2];
    const names=m[1].split(',').map(x=>x.trim().split(/\s+as\s+/)[0]).filter(Boolean);
    for (const n of names) if(!exportsMap[target]?.has(n)){console.log(`${f} imports missing ${n} from ${target}`);bad++;}
  }
}
console.log('bad imports:',bad, 'files:',files.length);
