  const cx = Math.floor(x / TILE), cy = Math.floor(y / TILE);
  for (let ty = cy - radius; ty <= cy + radius; ty++) {
    for (let tx = cx - radius; tx <= cx + radius; tx++) {
      if (tx < 0 || ty < 0 || tx >= world.W || ty >= world.H) continue;
